/* @lc app=leetcode id=3952 lang=kotlin */ class Solution { fun maxTotal(nums: IntArray, s: String): Long = (1 until nums.size).fold(listOf(0L, Long.MIN_VALUE / 4)) { f, i -> listOf(0, 1).map { b -> if (b == 1 && s[i] != '1') Long.MIN_VALUE / 4 else (0..1).maxOf { a -> if (f[a] < Long.MIN_VALUE / 8 || (a == 1 && s[i - 1] != '1')) Long.MIN_VALUE / 4 else f[a] + (if ((s[i - 1] == '1' && a == 0) || (s[i] == '1' && b == 1)) nums[i - 1].toLong() else 0L) } } }.let { f -> (0..1).maxOf { a -> if (f[a] < Long.MIN_VALUE / 8 || (a == 1 && s[nums.size - 1] != '1')) Long.MIN_VALUE / 4 else f[a] + (if (s[nums.size - 1] == '1' && a == 0) nums[nums.size - 1].toLong() else 0L) } } }